export function createLimitedMovesMode({hard:e=!1}={}){const o=e?20:25;return Object.freeze({id:"limitedMoves",moves:o,record:Object.freeze({key:"fewestMoves",field:"moves"}),getStatus:({seconds:e,moves:t,completed:s},m)=>({seconds:e,moves:`${t}/${o}`,timeLow:!1,movesLow:!s&&o-t<=m}),getDefeatReason:({moves:e,matches:t,pairCount:s,attemptResolved:m})=>m&&e>=o&&t<s?"moveLimit":null})}
